  const videoURLs = [];
  function videoSrc() {
    const i = ri(0, VIDEO_B64.length - 1);
    if (!videoURLs[i]) {
      const bin = atob(VIDEO_B64[i]);
      const arr = new Uint8Array(bin.length);
      for (let k = 0; k < bin.length; k++) arr[k] = bin.charCodeAt(k);
      videoURLs[i] = URL.createObjectURL(new Blob([arr], { type: 'video/webm' }));
    }
    return videoURLs[i];
  }

  function mkVideo(parent, w, h, css) {
    const v = document.createElement('video');
    v.src = videoSrc();
    v.muted = true;
    v.loop = true;
    v.autoplay = true;
    v.playsInline = true;
    v.setAttribute('muted', '');
    v.addEventListener('error', () => v.remove());
    Object.assign(v.style, {
      position: 'absolute', left: '0', top: '0', width: w + 'px', height: h + 'px',
      objectFit: 'cover', borderRadius: pick(['8px', '50%', '0']),
      boxShadow: '0 4px 12px rgba(0,0,0,.4)', border: '3px solid #fff', boxSizing: 'border-box'
    }, css);
    parent.appendChild(v);
    const p = v.play();
    if (p && p.catch) p.catch(() => { /* autoplay geblokkeerd */ });
    return v;
  }

